#define CHECK(x) do{++checks;if(!(x))throw std::runtime_error(std::string(#x)+" line "+std::to_string(__LINE__));}while(false)
template<class F>void run(const std::string& name,F f){f();++cases;std::cout<<"PASS "<<name<<std::endl;}
template<class F>void fails(F f){bool failed=false;try{f();}catch(const std::exception&){failed=true;}CHECK(failed);}
const std::string S1="11111111-1111-4111-8111-111111111111",S2="22222222-2222-4222-8222-222222222222",S3="33333333-3333-4333-8333-333333333333",S4="44444444-4444-4444-8444-444444444444";
std::string encode(const w::Envelope& v){std::string b;w::Error e;CHECK(w::EncodeEnvelope(v,b,e));return b;}
w::Envelope decode(const std::string& b){w::Envelope v;w::Error e;CHECK(w::DecodeEnvelope(reinterpret_cast<const uint8_t*>(b.data()),b.size(),v,e));return v;}
struct Source {
 w::TrustedHmdSourceAuthority a;w::TrustedHmdSourcePose p;
 explicit Source(std::string id="source-publisher-A"){
  std::ifstream f(std::string(ROOT_DIR)+"/third_party/monaka-protocol-v2/fixtures/v2.1/ordered-streams/source-normal.jsonl");std::string l;
  CHECK(bool(std::getline(f,l)));a=std::get<w::TrustedHmdSourceAuthority>(decode(l));CHECK(bool(std::getline(f,l)));p=std::get<w::TrustedHmdSourcePose>(decode(l));
  a.publisher_id=p.publisher_id=id;a.source_space.source_id=p.source.source_space.source_id="shared-source-id";
 }
};
std::vector<std::string> packets(const std::string& publisher){
 Source f(publisher);TrustedHmdCommonWorldCoordinator c(publisher,{"synthetic-bridge","common-A",{},0,publisher},[]{return "same-world";},[]{return "same-calibration";});
 CHECK(c.beginSourceSession(publisher,f.a.session_id,f.a.clock_id,f.a,0).status=="authority");
 CHECK(c.beginPublisherSession(S1,S2,0).status=="session");auto r=*c.owner().pendingTransition();
 auto events=c.commitWorldTransition({r,0,1,true},1);CHECK(events.size()==2);std::vector<std::string> b;for(const auto& v:events)b.push_back(encode(v));return b;
}
struct Fake final:CommonWorldDatagramTransport {
 DatagramSubmission mode=DatagramSubmission::Accepted;std::vector<std::string> bytes;
 bool connect()override{return true;}void close()noexcept override{}
 DatagramSubmissionResult submit(std::string_view b)override{bytes.emplace_back(b);return {mode,mode==DatagramSubmission::Accepted?b.size():0};}
};
struct Rig {
 Source f;fs::path path;std::shared_ptr<CommonWorldRevisionStore> store;Fake* sink;
 std::unique_ptr<CommonWorldLiveSender> sender;CommonWorldLiveSender::Source source;CommonWorldDurableReceipt receipt;
 Rig(fs::path dir,std::string pub="source-publisher-A",std::string epoch="identity-epoch"):f(pub),path(dir/"world.rev"){
  fs::create_directories(dir);store=std::make_shared<CommonWorldRevisionStore>(makeCommonWorldFileStorage(path),CommonWorldPersistentHighWater{"synthetic-bridge","common-A",{},0,pub});
  auto t=std::make_unique<Fake>();sink=t.get();sender=std::make_unique<CommonWorldLiveSender>(store,epoch,pub,std::move(t));
 }
 void durable(){source=sender->startSource(1);CHECK(sender->authorizeSource(source,f.a.publisher_id,f.a.session_id,f.a.clock_id,f.a,2).status=="authority");auto c=sender->commitSource(source,3);CHECK(c.eligible&&c.receipt);receipt=*c.receipt;CHECK(receipt.committed.sourcePublisher==f.a.publisher_id);}
 void live(){durable();CHECK(sender->connect());CHECK(sender->enablePublisher(receipt,S1,S2,4)=="queued");}
 void drain(){while(sender->snapshot().queued)CHECK(sender->pump().status=="local-accepted");}
};
std::string read(const fs::path& p){std::ifstream f(p,std::ios::binary);CHECK(bool(f));return {std::istreambuf_iterator<char>(f),{}};}
void write(const fs::path& p,const std::string& b){std::ofstream f(p,std::ios::binary|std::ios::trunc);f.write(b.data(),b.size());CHECK(f.good());}
